import json

def is_diamond_free(solver, A, n):
    """Check if the graph represented by A is diamond-free."""
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    edges = [solver.Value(A[i, j]), solver.Value(A[i, k]), solver.Value(A[i, l]),
